INSERT INTO articles (number, originalText, simplifiedText, practicalExample, curiosity, chapterId, keywordsTags) VALUES
(1, 'A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado Democrático de Direito e tem como fundamentos:', 'O Brasil é um país independente formado pela união de estados, distrito federal e municípios. Funciona como uma república democrática, onde o poder vem do povo.', 'Assim como uma empresa é formada por vários departamentos que trabalham juntos, o Brasil é formado por vários estados que trabalham juntos.', 'O Brasil é uma república federativa desde 1891, mas a atual Constituição é de 1988, criada após a redemocratização.', 1, 'República, Federação, Democracia'),
(2, 'São Poderes da União, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário.', 'O Brasil tem três poderes principais que funcionam de forma independente mas harmônica: o Legislativo (faz as leis), o Executivo (executa as leis) e o Judiciário (julga conflitos).', 'É como uma empresa: o conselho faz as regras, o presidente executa, e o jurídico resolve conflitos.', 'Essa separação de poderes foi criada por Montesquieu no século XVIII para evitar que um único poder tivesse muito poder.', 1, 'Poderes, Legislativo, Executivo, Judiciário'),
(3, 'Constituem objetivos fundamentais da República Federativa do Brasil: I - construir uma sociedade livre, justa e solidária; II - garantir o desenvolvimento nacional; III - erradicar a pobreza e a marginalização e reduzir as desigualdades sociais e regionais; IV - promover o bem de todos, sem preconceitos de origem, raça, sexo, cor, idade e quaisquer outras formas de discriminação.', 'O Brasil tem como objetivos principais: construir uma sociedade livre, justa e solidária; garantir desenvolvimento nacional; erradicar a pobreza e reduzir desigualdades; e promover o bem de todos.', 'São como os objetivos de uma empresa: crescer, lucrar, mas também ajudar a comunidade.', 'Esses objetivos foram estabelecidos em 1988 como forma de orientar todas as políticas públicas do país.', 1, 'Objetivos, Desenvolvimento, Igualdade'),
(4, 'A República Federativa do Brasil rege-se nas suas relações internacionais pelos seguintes princípios: I - independência nacional; II - prevalência dos direitos humanos; III - autodeterminação dos povos; IV - não-intervenção; V - igualdade entre os Estados; VI - solução pacífica dos conflitos; VII - repúdio ao terrorismo e ao racismo; VIII - cooperação entre os povos para o progresso da humanidade; IX - concessão de asilo político.', 'Nas relações internacionais, o Brasil segue princípios como: independência nacional, prevalência dos direitos humanos, autodeterminação dos povos, não-intervenção, igualdade entre os estados, solução pacífica de conflitos, repúdio ao terrorismo e racismo.', 'É como as regras de convivência entre vizinhos: respeito mútuo, não invadir a propriedade do outro, resolver conflitos conversando.', 'Esses princípios colocam o Brasil como um país que busca paz e cooperação internacional.', 1, 'Relações Internacionais, Direitos Humanos'),
(5, 'Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:', 'Todos são iguais perante a lei. Ninguém pode ser discriminado por raça, cor, sexo, idade ou qualquer outra característica. Garantem-se direitos como: liberdade de expressão, direito à vida, liberdade de consciência, direito de propriedade, entre outros.', 'Se você é negro, branco, homem, mulher, jovem ou idoso, a lei protege seus direitos da mesma forma.', 'Este é o artigo mais longo da Constituição, com 78 incisos, porque protege os direitos fundamentais de todos.', 1, 'Igualdade, Direitos Fundamentais'),
(6, 'São direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o lazer, a segurança, a proteção à maternidade e à infância, a assistência aos desamparados, na forma desta Constituição.', 'São direitos sociais: educação, saúde, alimentação, trabalho, moradia, lazer, segurança, proteção à maternidade e infância, e assistência aos desamparados.', 'O governo deve garantir que você tenha acesso a escola, hospital, comida e casa.', 'Esses direitos são chamados de "direitos de segunda geração" porque surgiram após os direitos individuais.', 1, 'Direitos Sociais, Educação, Saúde'),
(7, 'São direitos dos trabalhadores urbanos e rurais, além de outros que visem à melhoria de sua condição social: I - relação de emprego protegida contra despedida arbitrária ou sem justa causa, nos termos de lei complementar, que preverá indenizações compensatórias, dentre outras disposições; II - seguro-desemprego, em caso de desemprego involuntário; III - fundo de garantia do tempo de serviço; IV - salário mínimo, fixado em lei, nacionalmente unificado, capaz de atender a suas necessidades vitais básicas e às de sua família com moradia, alimentação, educação, saúde, lazer, vestuário, higiene e transporte; V - piso salarial proporcional à extensão e à complexidade do trabalho; VI - irredutibilidade do salário, salvo o disposto em convenção ou acordo coletivo; VII - garantia de salário, nunca inferior ao mínimo, para os que percebem remuneração variável; VIII - décimo terceiro salário com base na remuneração integral ou no valor da aposentadoria; IX - repouso semanal remunerado, preferencialmente aos domingos; X - remuneração do trabalho noturno superior à do diurno; XI - proteção do salário na forma da lei, constituindo crime sua retenção dolosa; XII - salário-família pago em razão do dependente do trabalhador de baixa renda nos termos da lei; XIII - duração do trabalho normal não superior a oito horas diárias e quarenta e quatro semanais, facultado a compensação de horários e a redução da jornada, mediante acordo ou convenção coletiva de trabalho; XIV - segurança e higiene do trabalho; XV - proibição de trabalho noturno, perigoso ou insalubre a menores de dezoito e de qualquer trabalho a menores de dezesseis anos, salvo na condição de aprendiz; XVI - direitos à associação profissional ou sindical do trabalhador, inclusive o direito de greve, ressalvadas as disposições de lei complementar; XVII - gozo de férias anuais remuneradas com, pelo menos, um terço a mais do que o salário normal; XVIII - licença à gestante, sem prejuízo do emprego e do salário, com duração de cento e vinte dias; XIX - licença-paternidade, nos termos fixados em lei; XX - proteção do mercado de trabalho da mulher, mediante incentivos específicos, nos termos da lei; XXI - aviso prévio proporcional ao tempo de serviço, sendo no mínimo de trinta dias, nos termos da lei; XXII - redução dos riscos inerentes ao trabalho, por meio de normas de saúde, higiene e segurança; XXIII - adicional de remuneração para as atividades penosas, insalubres ou perigosas, na forma da lei; XXIV - aposentadoria; XXV - assistência gratuita aos filhos e dependentes desde o nascimento até cinco anos de idade em creches e pré-escolas; XXVI - reconhecimento das convenções e acordos coletivos de trabalho; XXVII - proteção em face da automação, na forma da lei; XXVIII - seguro contra acidentes de trabalho, a cargo do empregador, sem excluir a indenização a que está obrigado, quando incorrer em dolo ou culpa; XXIX - ação, quanto aos créditos resultantes das relações de trabalho, com prazo prescricional de cinco anos para os trabalhadores urbanos e rurais, até o limite de dois anos após a extinção do contrato de trabalho, garantida a execução física da sentença; XXX - proibição de difer
